// Generates src/db/migrations.gen.ts from drizzle-kit output. The SQL files are imported
// as text so they end up inside the compiled binary without any filesystem lookups.
import { join } from "node:path"

const root = join(import.meta.dir, "..")
const journal = (await Bun.file(join(root, "drizzle/meta/_journal.json")).json()) as {
  entries: { idx: number; tag: string }[]
}

const entries = [...journal.entries].sort((a, b) => a.idx - b.idx)
const lines = [
  "// Generated by scripts/gen-migrations.ts. Do not edit.",
  '/// <reference path="./sql.d.ts" />',
  ...entries.map((e) => `import m${e.idx} from "../../drizzle/${e.tag}.sql" with { type: "text" }`),
  "",
  "export const migrations: { tag: string; sql: string }[] = [",
  ...entries.map((e) => `  { tag: "${e.tag}", sql: m${e.idx} },`),
  "]",
  "",
]
await Bun.write(join(root, "src/db/migrations.gen.ts"), lines.join("\n"))
console.log(`wrote ${entries.length} migration(s)`)
